#!/usr/bin/env python3
"""Render a single offline HTML report; all evidence and styling are embedded."""
import datetime
import html
import json
import pathlib
import sys
from receipts import load, make_receipt

RUN=pathlib.Path(sys.argv[1]).resolve()
OUTPUT=pathlib.Path(sys.argv[2]).resolve()
rows=load(RUN/'prepared-current.json',[])
publications=load(RUN/'publications.json',{})
history=load(RUN/'compiler-history.json',{})
receipts=[make_receipt(RUN,row) for row in rows]
by_name={receipt['name']:receipt for receipt in receipts if receipt}
verified=sum(receipt['status']=='verified' for receipt in by_name.values())
blocked=sum(receipt['status']=='blocked' for receipt in by_name.values())
build_only=sum(receipt['status']=='build-only' for receipt in by_name.values())
pending=len(rows)-len(by_name)
published=sum(item.get('deployment')=='success' for item in publications.values())
e=html.escape
def b(value):return f'{value:,}' if isinstance(value,(int,float)) else '—'
def sec(value):return f'{value:.3f}' if isinstance(value,(int,float)) and value<1 else f'{value:.2f}' if isinstance(value,(int,float)) else '—'
def delta(receipt):
    a=receipt['sizes'].get('previous') or {}; z=receipt['sizes'].get('current') or {}
    return z['brotli11']-a['brotli11'] if isinstance(a.get('brotli11'),int) and isinstance(z.get('brotli11'),int) else None
table=[];cards=[]
blocker_notes={'mdast-util-from-markdownlil':'126 failing tests after a fresh build; earlier distribution passes.', 'micromarklil':'323 failing tests after a fresh build; earlier distribution passes.', 'remark-parselil':'2 failing checks after a fresh build; earlier distribution passes.', 'remarklil':'6 failing checks after a fresh build; earlier distribution passes.', 'zodlil':'344 failing production-mode tests; earlier distribution passes.', 'motionlil':'Node suite passes, but browser execution throws a temporal-dead-zone ReferenceError and an iterable TypeError.', 'react-markdownlil':'120 runtime tests pass. TypeScript fails on an existing npm dependency declaration; the earlier distribution fails the same check.', 'vuelil':'The compiler rejects runtime-core generation with a callable ABI mismatch. The full build stops there.', 'monacolil':'Build completes, but no repository behavior gate establishes compatibility.'}
blocker_rows=''.join('<tr><th><a href="#'+e(name)+'">'+e(name)+'</a></th><td style="white-space:normal;text-align:left">'+e(note)+'</td></tr>' for name,note in blocker_notes.items())
for row in rows:
    name=row['name'];receipt=by_name.get(name);pub=publications.get(name,{})
    if not receipt:
        table.append(f'<tr data-name="{e(name)}" data-status="pending"><th>{e(name)}</th><td><span class="badge pending">pending</span></td><td colspan="7">Audit still running</td></tr>')
        continue
    status=receipt['status'];sizes=receipt['sizes'];timing=receipt['timing'];change=delta(receipt)
    old=sizes.get('previous') or {};new=sizes.get('current') or {};original=sizes.get('upstream') or {}
    live='live' if pub.get('deployment')=='success' else pub.get('deployment',pub.get('status','not published'))
    table.append(f'<tr data-name="{e(name)}" data-status="{e(status)}"><th><a href="#{e(name)}">{e(name)}</a></th><td><span class="badge {e(status)}">{e(status)}</span></td><td>{b(old.get("brotli11"))}</td><td>{b(new.get("brotli11"))}</td><td class="{("better" if change<0 else "worse") if change is not None else ""}">{f"{change:+,}" if change is not None else "—"}</td><td>{b(original.get("brotli11"))}</td><td>{sec(timing.get("packageSeconds"))}</td><td>{sec(timing.get("upstreamSeconds"))}</td><td>{e(live)}</td></tr>')
    hardware=receipt['machine'];upstream=receipt['upstream'];behavior=receipt['behavior']
    link=f'https://github.com/yeargun/{name}'
    commit_link=f'{link}/commit/{pub["commit"]}' if pub.get('commit') else link
    findings=''.join('<li>'+e(str(item))+'</li>' for item in receipt['findings'])
    if name=='solidlil':findings+='<li>The Pages deployment passes. The separate Node 18 CI job still fails because its current development toolchain requires newer Node APIs; this audit used Node 22.23.2.</li>'
    cards.append(f'''<article id="{e(name)}" class="card" data-name="{e(name)}" data-status="{e(status)}">
<div class="card-head"><h2>{e(name)}</h2><span class="badge {e(status)}">{e(status)}</span></div>
<p>{e(receipt['summary'])}</p><p class="links"><a href="{link}">GitHub</a> · <a href="https://yeargun.github.io/{e(name)}/">comparison page</a> · <a href="{commit_link}">{e(live)}</a> · <a href="{link}/tree/{row['baseCommit']}">measured source</a></p>
<ul>{findings or '<li>The fresh build and recorded page artifact have no measured Brotli drift.</li>'}</ul>
<div class="two"><div><h3>Behavior and versions</h3><p>{e(behavior['summary'])}</p><p>Port source <code>{e(row['baseCommit'])}</code><br>GitHub at start <code>{e(row['publicCommit'])}</code></p><p>Upstream target: <strong>{e(str(upstream.get('package','source fixture')))}@{e(str(upstream.get('pinned','git-pinned')))}</strong><br>Registry latest: {e(str(upstream.get('latest','not a registry lane')))}</p><p>{e(str(upstream.get('note','No compatibility upgrade to newer upstream versions was attempted.')))}</p></div>
<div><h3>Build machine and time</h3><p><strong>Azure {e(hardware['instanceClass'])}</strong><br>{e(hardware['cpu'])}<br>{hardware['logicalCpus']} logical CPUs · {hardware['memoryBytes']/2**30:.1f} GiB RAM · {e(hardware['os'])}<br>Node {e(hardware['node'])} · Rayon {hardware['rayonThreads']} threads</p>
<dl><dt>Primary ESM compiler invocation</dt><dd>{sec(timing.get('primaryCompilerSeconds'))} s</dd><dt>Complete LilScript package {'build' if receipt['buildPassed'] else 'attempt'}</dt><dd>{sec(timing.get('packageSeconds'))} s</dd><dt>Original comparison bundle</dt><dd>{sec(timing.get('upstreamSeconds'))} s</dd></dl></div></div>
<p class="scope">{e(receipt['comparisonScope'])}</p><p class="small">{e(timing['protocol'])}</p>
<details><summary>Exact commands, failure details, and artifact hashes</summary><p>Port build: <code>{e(timing['packageScope'])}</code></p><p>Upstream scope: {e(timing['upstreamScope'])}</p><p>Behavior command: <code>{e(str(behavior.get('command')))}</code></p><pre>{e(json.dumps(receipt,indent=2))}</pre></details></article>''')
generated=datetime.datetime.now(datetime.timezone.utc).strftime('%Y-%m-%d %H:%M UTC')
data_json=json.dumps({'generatedAt':generated,'compiler':history,'libraries':list(by_name.values()),'publication':publications},ensure_ascii=False).replace('<','\\u003c')
document=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>LilScript library drift · 10 September 2026</title>
<style>:root{{--paper:#f7f5ef;--ink:#182b31;--muted:#53666d;--line:#d8dfdc;--accent:#006b79}}*{{box-sizing:border-box}}html{{scroll-behavior:smooth}}body{{margin:0;background:var(--paper);color:var(--ink);font:16px/1.6 system-ui,sans-serif}}header,main,footer{{max-width:1320px;margin:auto;padding:32px}}header{{padding-top:64px}}.eyebrow{{text-transform:uppercase;letter-spacing:.14em;color:var(--accent);font-size:12px;font-weight:700}}h1{{font-size:clamp(38px,6vw,72px);line-height:1.06;max-width:950px;letter-spacing:-.04em;margin:18px 0}}h2{{font-size:25px;line-height:1.25;margin:0}}h3{{font-size:16px;margin:22px 0 8px}}p{{max-width:100ch}}.lede{{font-size:21px;max-width:850px;color:var(--muted)}}.stamp,.small{{font-size:13px;color:var(--muted)}}.stats{{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-top:32px}}.stat{{border-top:2px solid var(--accent);padding:16px 0}}.stat strong{{font-size:36px;display:block}}.stat span{{font-size:14px;color:var(--muted)}}.method,.card{{background:#fff;border:1px solid var(--line);border-radius:14px;padding:28px;margin:24px 0}}.two{{display:grid;grid-template-columns:1fr 1fr;gap:36px}}a{{color:var(--accent);text-underline-offset:3px}}.toolbar{{display:flex;gap:12px;flex-wrap:wrap;margin:24px 0}}input,select,button{{font:inherit;padding:10px 14px;border:1px solid #a8bcbf;background:white;border-radius:7px;color:var(--ink)}}input{{flex:1;min-width:210px}}button{{cursor:pointer}}.table-wrap{{overflow:auto;border:1px solid var(--line);border-radius:12px;background:white}}table{{border-collapse:collapse;width:100%;font-size:14px}}th,td{{padding:13px 12px;border-bottom:1px solid var(--line);white-space:nowrap;text-align:right}}th:first-child,td:first-child{{text-align:left}}thead{{background:#e8f1f0}}tbody th{{font-weight:550}}.badge{{font-size:12px;font-weight:650;padding:5px 9px;border-radius:16px;background:#eef1f2;white-space:nowrap}}.verified{{background:#e4f3e9;color:#14653a}}.blocked{{background:#ffede4;color:#943f11}}.build-only,.pending{{background:#eef0fb;color:#465791}}.better{{color:#11633a}}.worse{{color:#a34c27}}.card-head{{display:flex;align-items:center;justify-content:space-between;gap:14px}}.links{{font-size:14px}}code{{font:12px/1.5 ui-monospace,monospace;overflow-wrap:anywhere}}pre{{white-space:pre-wrap;overflow-wrap:anywhere;background:#f0f4f3;padding:18px;max-height:500px;overflow:auto;font-size:11px}}details{{border-top:1px solid var(--line);padding-top:15px;margin-top:20px}}summary{{cursor:pointer;font-weight:550}}dl{{display:grid;grid-template-columns:1fr auto;gap:6px 20px}}dd{{margin:0;font-variant-numeric:tabular-nums}}dt{{color:var(--muted)}}.scope{{background:#eef5f5;padding:15px;border-radius:7px;font-size:14px}}li{{margin:8px 0}}footer{{color:var(--muted);font-size:13px}}[hidden]{{display:none!important}}@media(max-width:750px){{header,main,footer{{padding:22px}}.stats{{grid-template-columns:1fr 1fr}}.two{{grid-template-columns:1fr;gap:0}}.card,.method{{padding:20px}}}}@media print{{.toolbar{{display:none}}body{{background:white}}.card{{break-inside:avoid}}a{{color:inherit}}details pre{{max-height:none}}}}</style></head><body>
<header><p class="eyebrow">LilScript · published evidence audit</p><h1>LilScript library drift<br>and build comparisons.</h1><p class="lede">A fresh audit of 27 GitHub Pages library comparisons, using a release compiler rebuilt from the exact <code>63c2896</code> migration checkpoint.</p><p class="stamp">Generated {generated}. {'IN PROGRESS — '+str(pending)+' libraries still running.' if pending else 'All library build attempts are recorded.'}</p><div class="stats"><div class="stat"><strong>{len(rows)}</strong><span>library sites inventoried</span></div><div class="stat"><strong>{verified}</strong><span>fresh build + repository gate passed</span></div><div class="stat"><strong>{blocked}</strong><span>build/test blockers disclosed</span></div><div class="stat"><strong>{published}</strong><span>Pages deployments verified</span></div></div></header>
<main><section class="method"><h2>What drifted</h2><div class="two"><div><h3>Compiler and language behavior</h3><p>The starting checkout was <code>54e1948</code>, while the current compiler work was in <code>migration/target-tree</code> at <code>63c2896</code>, 316 commits ahead of that checkout. The public compiler branch was older again. The exact <a href="https://github.com/yeargun/lilscript/tree/comparison-snapshot-2026-09-10">compiler source snapshot</a> is now available on GitHub. A shared binary and the visible source checkout were therefore insufficient provenance.</p><p>The newer branch changes JavaScript generation to a structured target tree, adds configuration choices such as <code>name_ordering</code>, <code>terminal_cleanup_chain</code> and <code>wide_single_use_collapse</code>, and contains fixes for variable freshness, parameter redeclarations, catch parameters and function bindings. The artifact hash and tests determine whether a particular port is eligible.</p><h3>Pages and repository drift</h3><p>Sixteen ports had committed changes absent from GitHub when this audit began. Most site builders copied saved JSON rather than recompiling. Existing size, test-count and runtime claims could therefore describe different artifacts.</p></div><div><h3>Comparison scope</h3><p>Dependencies left external by a LilScript artifact must also remain external in the upstream reference. The rehype-katex comparison violated this boundary. Prototype or partial ports, including Monaco and Solid, do not gain full-library parity merely by producing a small bundle.</p><h3>Time and machine</h3><p>Builds ran on Azure <strong>Standard_D16als_v7</strong> workers, AMD EPYC 9V45, 16 logical CPUs and about 31.3 GiB RAM, with Ubuntu 24.04.4. Vue used Node 24.11.1; the other lanes used Node 22.23.2.</p><p>The audit scheduled one port per worker, but other compiler jobs were observed in the shared pool. Timings include that uncertainty. Original timings describe production comparison-bundle builds from pinned upstream inputs, not complete vendor release pipelines; full package and single ESM timings must not be turned into a misleading speedup ratio.</p></div></div><p class="small">User worktrees and uncommitted changes were preserved. Failed or unverified rebuilds remain diagnostic; their prior public runtime is retained. Pinned upstream versions are explicit, and npm's latest dist-tag is recorded separately. The old lil-solidjs repository points to SolidLil; lilscript-solid-lab has no Pages site. These historical repositories are not counted as additional comparison sites.</p></section>
<section class="method"><h2>What still needs work</h2><p>The {blocked} blocked candidates and {build_only} build-only candidate retain their previous public distributions. Their pages now show the fresh diagnostic measurements and the reason promotion was withheld. These findings identify the failing boundary; they do not by themselves isolate every failure to a compiler pass.</p><div class="table-wrap"><table><tbody>{blocker_rows}</tbody></table></div></section>
<section aria-labelledby="overview"><h2 id="overview">All libraries</h2><p>Brotli values are bytes. Build values are seconds. “Verified” means the recorded repository command passed on the rebuilt distribution; scope limitations remain in each receipt.</p><div class="toolbar"><input id="filter" type="search" placeholder="Filter libraries or findings" aria-label="Filter libraries"><select id="status" aria-label="Filter result"><option value="all">All results</option><option value="verified">Verified</option><option value="blocked">Blocked</option><option value="build-only">Build only</option><option value="pending">Pending</option></select><button id="download">Download evidence JSON</button><button onclick="window.print()">Print / PDF</button></div><div class="table-wrap"><table><thead><tr><th>Library</th><th>Fresh check</th><th>Published Br</th><th>Fresh Br</th><th>Drift</th><th>Original Br</th><th>Lil package s</th><th>Original ESM s</th><th>Page update</th></tr></thead><tbody>{''.join(table)}</tbody></table></div></section>{''.join(cards)}
<section class="method"><h2>Verification and interpretation</h2><ul><li>Compilation started from a clean committed source snapshot. Existing JavaScript distribution files were removed before each build; failed builds cannot fall back to old sizes.</li><li>The compiler wrapper recorded real invocations, output hashes and wall time. Canonical gzip and Brotli encoders measured exact file bytes after the build.</li><li>Repository behavior commands ran against the earlier distribution and the fresh output where available. Browser prerequisites, lockfile repairs, mode differences and unresolved failures are disclosed.</li><li>Local browser checks load the generated comparison pages and require the machine panel. Deployment verification checks the exact commit’s Pages workflow and compares its live JSON receipt with the published file.</li><li>Each updated Pages build checks its source/configuration fingerprint and served artifact hashes. A later source or artifact edit must refresh its receipt before Pages can publish.</li><li>Historical runtime throughput is not silently attributed to this compiler. Source changes and compiler changes are both present, so published-to-fresh byte drift is not a compiler-only A/B result.</li></ul><details><summary>Reproduce the selected compiler</summary><pre>git clone --branch comparison-snapshot-2026-09-10 https://github.com/yeargun/lilscript.git
cd lilscript
cargo build --release --bin lilscript --bin lilscript-codec</pre><p>Use each card’s measured-source link and exact package build command. Set LILSCRIPT_COMPILER and LILSCRIPT_CODEC to these release binaries. Install locked dependencies first; ports that import sibling sources also need those recorded sibling checkouts. Repair prerequisites and comparison scopes are disclosed in the receipts. A new hardware or compiler run must create a new measurement, not reuse the times in this report.</p></details><details><summary>Compiler history selected for the audit</summary><pre>{e(chr(10).join(history.get('changes',[])))}</pre></details></section></main><footer>This HTML is self-contained. Repository and Pages links require a network connection; the report, filters, measurements and embedded evidence work offline. Generated from exact source commits, live Pages snapshots, npm registry queries, build logs and artifact receipts.</footer>
<script id="evidence" type="application/json">{data_json}</script><script>const evidence=JSON.parse(document.getElementById('evidence').textContent);const filter=document.getElementById('filter'),status=document.getElementById('status');function apply(){{const q=filter.value.toLowerCase();for(const node of document.querySelectorAll('[data-name]')){{const name=node.dataset.name;const receipt=evidence.libraries.find(x=>x.name===name);const text=name+' '+(receipt?.findings??[]).join(' ');node.hidden=!(text.toLowerCase().includes(q)&&(status.value==='all'||node.dataset.status===status.value));}}}}filter.addEventListener('input',apply);status.addEventListener('change',apply);document.getElementById('download').addEventListener('click',()=>{{const url=URL.createObjectURL(new Blob([JSON.stringify(evidence,null,2)],{{type:'application/json'}}));const a=document.createElement('a');a.href=url;a.download='lilscript-library-drift-evidence.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}});</script></body></html>'''
OUTPUT.write_text(document)
(RUN/'receipts.json').write_text(json.dumps(list(by_name.values()),indent=2)+'\n')
print(f'{OUTPUT}: {len(by_name)}/{len(rows)} receipts; {verified} verified, {blocked} blocked, {published} live')
